def keys_unique_to_one(dicts_list):
    counts = {}
    for d in dicts_list:
        for k in d:
            counts[k] = counts.get(k, 0) + 1
    return sorted(k for k, cnt in counts.items() if cnt == 1)

def filter_by_key_and_value(d, prefix, min_value):
    return {
        k: v
        for k, v in d.items()
        if k.startswith(prefix) and v >= min_value
    }

def top_k_by_value(d, k):
    if k <= 0:
        return []
    items = sorted(d.items(), key=lambda kv: (-kv[1], kv[0]))
    return items[:k]

def rank_by_value_competition(d):
    items = sorted(d.items(), key=lambda kv: -kv[1])
    result = {}
    for i, (k, v) in enumerate(items):
        if i > 0 and v == items[i - 1][1]:
            rank = result[items[i - 1][0]]
        else:
            rank = i + 1
        result[k] = rank
    return result

def rank_by_value_dense(d):
    distinct = sorted(set(d.values()), reverse=True)
    rank_map = {v: i + 1 for i, v in enumerate(distinct)}
    return {k: rank_map[v] for k, v in d.items()}

def second_highest_value(d):
    distinct = sorted(set(d.values()), reverse=True)
    if len(distinct) < 2:
        return None
    return distinct[1]

def value_span(d):
    if len(d) < 2:
        return 0
    vals = d.values()
    return max(vals) - min(vals)

def count_word_trigrams(words):
    result = {}
    for i in range(len(words) - 2):
        tri = (words[i], words[i + 1], words[i + 2])
        result[tri] = result.get(tri, 0) + 1
    return result

def count_char_bigrams(s):
    result = {}
    for i in range(len(s) - 1):
        bg = s[i:i + 2]
        result[bg] = result.get(bg, 0) + 1
    return result

def merge_keys_case_insensitive(d):
    result = {}
    for k, v in d.items():
        lk = k.lower()
        result[lk] = result.get(lk, 0) + v
    return result

def count_unordered_pairs(pairs):
    result = {}
    for a, b in pairs:
        key = (a, b) if a <= b else (b, a)
        result[key] = result.get(key, 0) + 1
    return result

def most_common_pair(pairs):
    counts = {}
    for p in pairs:
        counts[p] = counts.get(p, 0) + 1
    best = None
    best_count = -1
    for p, c in counts.items():
        if c > best_count or (c == best_count and p < best):
            best = p
            best_count = c
    return best

def value_occurrence_counts(d):
    result = {}
    for v in d.values():
        result[v] = result.get(v, 0) + 1
    return result

def digit_frequency(nums):
    result = {}
    for n in nums:
        for ch in str(abs(n)):
            result[ch] = result.get(ch, 0) + 1
    return result
